witnesses.repro_duckdb_sql:
SET TimeZone = 'UTC';
SELECT r0."user_id" AS hop_0_pk, r1."post_id" AS hop_1_pk, r2."vote_id" AS hop_2_pk, CAST(r2."available_at" AS TIMESTAMPTZ) AS available_at, TIMESTAMPTZ '2024-06-01T00:00:00Z' AS prediction_cutoff, epoch(CAST(r2."available_at" AS TIMESTAMPTZ) - TIMESTAMPTZ '2024-06-01T00:00:00Z') AS delta_seconds
FROM read_csv('tables/users.csv', header=true, all_varchar=true, delim=',') AS r0
JOIN read_csv('tables/posts.csv', header=true, all_varchar=true, delim=',') AS r1 ON r0."user_id" = r1."user_id"
JOIN read_csv('tables/votes.csv', header=true, all_varchar=true, delim=',') AS r2 ON r1."post_id" = r2."post_id"
WHERE r0."user_id" = 'u001' AND r1."post_id" = 'p001' AND r2."vote_id" = 'v002' AND CAST(r2."available_at" AS TIMESTAMPTZ) >= TIMESTAMPTZ '2024-06-01T00:00:00Z';
